pub const SupportingSource = struct {
    path: []const u8,
    purpose: []const u8,
    /// SOURCE_SHA256: LF-normalized whole-file hash at generation time.
    source_sha256: []const u8,
};

pub const supporting_sources = [_]SupportingSource{
    .{ .path = "packages/core/tools/src/schema.ts", .purpose = "parameter DSL to JSON Schema compiler semantics", .source_sha256 = "096f679e38626cc52536b8ecb9eef4c551c1a8a095c8e84f7a3b6156ee533653" },
    .{ .path = "packages/core/tools/src/presentation.ts", .purpose = "tool presentation vocabulary", .source_sha256 = "2e729538403ef924430187df13ec5e140de95e0ea41a8225093dba644c1f2b6a" },
    .{ .path = "packages/bundle/base/cordis.patch.yml", .purpose = "deployment defaults for conditional text and the plan:policy section", .source_sha256 = "a2cc57868a4d016609801e28781262515483dde29b41c2742d9a3b27a6f52f77" },
    .{ .path = "packages/subprocess/subprocess/src/types.ts", .purpose = "DSH_ENV_PREFIX used by the bash description", .source_sha256 = "e65166444ff791994a7198a86ac4a821e8329120bd551f342913623c87e5a715" },
};

test "generated content hashes match recorded values" {
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    for (sources) |source| {
        std.crypto.hash.sha2.Sha256.hash(source.content, &digest, .{});
        const hex = std.fmt.bytesToHex(digest, .lower);
        try std.testing.expectEqualStrings(source.content_sha256, &hex);
        try std.testing.expectEqual(@as(usize, 64), source.source_sha256.len);
        try std.testing.expect(source.line_start >= 1);
        try std.testing.expect(source.line_end >= source.line_start);
    }
    for (system_prompt.section_order_sources) |source| {
        try std.testing.expectEqual(@as(usize, 64), source.source_sha256.len);
        try std.testing.expect(source.line_start >= 1);
        try std.testing.expect(source.line_end >= source.line_start);
    }
    for (supporting_sources) |source| {
        try std.testing.expectEqual(@as(usize, 64), source.source_sha256.len);
        try std.testing.expect(source.path.len > 0);
    }
}
